WITH exploded AS (SELECT id, created_at, pos, li_item.product_id, li_item.qty, li_item.price, li_item.promo FROM carts LATERAL VIEW OUTER POSEXPLODE(items) t AS pos, li_item) SELECT CASE WHEN product_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS product_id_tier, DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(CASE WHEN promo = 'WELCOME5' THEN 1 END) AS welcome5_count, AVG(product_id) AS avg_product_id, APPROX_PERCENTILE(price, 0.5) AS price_p50, MIN(created_at) AS started_at, MIN(created_at) AS first_seen, COUNT_IF(promo = 'SPRING10') AS spring10_events FROM exploded GROUP BY product_id_tier, activity_day ORDER BY product_id_tier DESC NULLS FIRST;
